import { expect, expectStatus, test } from "../../fixtures";

test.describe("upload vendor documents", () => {
  test("documents cannot be added to a vendor under review", { tag: "@DOC-06" }, async ({ apiAs }) => {
    // Arrange: a member creates a uniquely named vendor and submits it, moving it to in_review.
    const member = await apiAs("member");
    const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
    const created = await expectStatus(
      await member.post("/api/vendors", {
        data: {
          name: `DOC-06 Vendor ${suffix}`,
          category: "services",
          contact_email: `doc-06-${suffix}@northwind.test`,
        },
      }),
      201,
    );
    expect(created.status).toBe("draft");

    const submitted = await expectStatus(
      await member.post(`/api/vendors/${created.id}/submit`),
      200,
    );
    expect(submitted.status).toBe("in_review");

    // Act: attempt to upload a W-9 to the vendor under review.
    const response = await member.post(`/api/vendors/${created.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9.txt",
          mimeType: "text/plain",
          buffer: Buffer.from(`W-9 for ${suffix}`),
        },
      },
    });

    // Assert
    const body = await expectStatus(response, 409);
    expect(body.error.code).toBe("vendor_locked");
  });
});
